// Determina se o envio foi bem-sucedido
const item = $input.first().json;
const channel = $('Dividir Lembretes').item.json.channel;
const reminderId = $('Dividir Lembretes').item.json.id;

// Para WhatsApp: se houver messages array no resultado, foi sucesso
// Para E-mail: se houver success=true, foi sucesso
const waSuccess = item.messages || item.success || item.id;
const emailSuccess = item.success === true;

const isSuccess = channel === 'whatsapp' ? !!waSuccess : !!emailSuccess;
const errorMsg = !isSuccess ? JSON.stringify(item) : null;

return [{
  json: {
    reminder_id: reminderId,
    channel,
    success: isSuccess,
    provider_message_id: item.messages?.[0]?.id ?? item.resend_id ?? null,
    error: errorMsg,
  }
}];

